spec.setup_code:
var c = null;
var N = 16, T = 14;
var WARM = '#B4552F', BLUE = '#0B4FC0', INK = '#04204B', SEC = '#3D5F91', FAINT = '#8098BC';
function rng(seed) { var s = seed; return function () { s = (s * 1664525 + 1013904223) % 4294967296; return s / 4294967296; }; }
var rnd = rng(11);
var raw = [], nrmV = [], ga_ = [], be_ = [], amp = [], xr = [], wf = [];
var mu = 0, sd = 0, i;
for (i = 0; i < N; i++) {
  raw.push(1.0 + 0.95 * (rnd() * 2 - 1));
  ga_.push(rnd() * 2 - 1);
  be_.push(rnd() * 2 - 1);
  amp.push(0.6 + 0.6 * rnd());
  wf.push(rnd() * 6);
  xr.push(0.9 * Math.sin(i * 0.7 + 0.5) + 0.35 * (rnd() * 2 - 1));
}
for (i = 0; i < N; i++) mu += raw[i] / N;
for (i = 0; i < N; i++) sd += (raw[i] - mu) * (raw[i] - mu) / N;
sd = Math.sqrt(sd);
for (i = 0; i < N; i++) nrmV.push((raw[i] - mu) / sd);
var meanAmp = 0;
for (i = 0; i < N; i++) meanAmp += amp[i] / N;

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function sm(x) { x = clamp(x, 0, 1); return x * x * (3 - 2 * x); }
function ease(t, a, b) { return sm((t - a) / (b - a)); }
function lerp(a, b, k) { return a + (b - a) * k; }
var pts = [[0, 0.5], [3.5, 0.5], [4.2, 0.1], [5.2, 0.1], [6.8, 0.9], [8.0, 0.9], [8.9, 0.5], [14, 0.5]];
function sOf(t) {
  for (var k = 0; k < pts.length - 1; k++) {
    if (t <= pts[k + 1][0]) {
      var f = (t - pts[k][0]) / (pts[k + 1][0] - pts[k][0]);
      return lerp(pts[k][1], pts[k + 1][1], sm(f));
    }
  }
  return 0.5;
}
function txt(s, x, y, size, col, al, maxW, bold) {
  var z = size;
  c.font = (bold ? 'bold ' : '') + z + 'px sans-serif';
  if (maxW) {
    while (z > 11 && c.measureText(s).width > maxW) { z -= 0.5; c.font = (bold ? 'bold ' : '') + z + 'px sans-serif'; }
  }
  c.fillStyle = col;
  c.textAlign = al || 'left';
  c.fillText(s, x, y);
}
function head(x0, y0, x1, y1, sz) {
  var a = Math.atan2(y1 - y0, x1 - x0);
  c.beginPath();
  c.moveTo(x1, y1);
  c.lineTo(x1 - sz * Math.cos(a - 0.45), y1 - sz * Math.sin(a - 0.45));
  c.lineTo(x1 - sz * Math.cos(a + 0.45), y1 - sz * Math.sin(a + 0.45));
  c.closePath();
  c.fill();
}
function line(x0, y0, x1, y1) { c.beginPath(); c.moveTo(x0, y0); c.lineTo(x1, y1); c.stroke(); }
function arrow(x0, y0, x1, y1) { line(x0, y0, x1, y1); head(x0, y0, x1, y1, 6); }
function dot(x0, y0, x1, y1, time, off) {
  var u = (time * 0.7 + off) % 1;
  c.beginPath();
  c.arc(lerp(x0, x1, u), lerp(y0, y1, u), 2.4, 0, 6.2832);
  c.fill();
}

return {
  draw: function (ctx, W, H, time, dt) {
    c = ctx;
    c.fillStyle = '#ffffff';
    c.fillRect(0, 0, W, H);
    var ky = H / 400;
    function Y(v) { return v * ky; }
    var t = time % T;
    var f = 1 - ease(t, 13.3, 14);
    var phase = t < 3.5 ? 0 : (t < 8.5 ? 1 : 2);
    var pst = [0, 3.5, 8.5][phase];
    var fadeIn = clamp((t - pst) / 0.4, 0, 1) * (1 - ease(t, 13.5, 14));
    var s = sOf(t);
    var nrm = ease(t, 0.6, 2.8) * f;
    var mod = ease(t, 3.5, 4.5) * f;
    var fa = ease(t, 8.6, 9.6) * f;
    var gaA = ease(t, 9.0, 9.8) * f;
    var p = sm((t - 9.4) / 3.8) * f;
    var m = W * 0.07;
    var pitch = (W - 2 * m) / N, bw = pitch * 0.62;
    var unitF = Y(13), unitR = Y(12);
    var featCy = Y(208), resCy = Y(98);
    c.lineWidth = 1;
    c.globalAlpha = 1;

    // modulation values from MLP(sigma)
    var gam = [], bet = [], yFull = [], F = [], disp = [], base = [], alp = [];
    for (i = 0; i < N; i++) {
      gam.push(0.75 * ga_[i] * (2 * s - 1));
      bet.push(0.9 * be_[i] * (2 * s - 1) + 0.15 * Math.sin(i * 1.7));
      yFull.push((1 + gam[i]) * nrmV[i] + bet[i]);
      F.push(1.5 * Math.sin(1.3 * yFull[i] + wf[i]));
      base.push(lerp(raw[i], nrmV[i], nrm));
      disp.push(lerp(lerp(base[i], yFull[i], mod), F[i], fa));
      alp.push(p * amp[i]);
    }

    // caption
    var caps = ['1 · normalise: zero mean, unit spread', '2 · scale and shift: (1 + γ)·h + β', '3 · gate: x + α·F(h)'];
    c.globalAlpha = fadeIn;
    txt(caps[phase], W / 2, Y(18), 13, INK, 'center', W - 16, true);
    c.globalAlpha = 1;

    // training bar
    var tbw = Math.min(220, W * 0.45), lw = 52;
    var tx0 = (W - (lw + 8 + tbw)) / 2;
    c.globalAlpha = 0.45 + 0.55 * ease(t, 8.5, 9.2);
    txt('training', tx0, Y(44), 12, SEC, 'left');
    c.strokeStyle = FAINT;
    c.strokeRect(tx0 + lw + 8, Y(35), tbw, Y(9));
    c.fillStyle = WARM;
    c.fillRect(tx0 + lw + 8, Y(35), tbw * p, Y(9));
    c.globalAlpha = 1;

    // residual stream row
    txt(gaA > 0.5 ? 'x + α·F(h)   residual stream' : 'x   residual stream', m, Y(64), 12, SEC, 'left', W - 2 * m);
    c.strokeStyle = FAINT;
    line(m, resCy, W - m, resCy);
    for (i = 0; i < N; i++) {
      var bx = m + i * pitch + (pitch - bw) / 2;
      var v0 = xr[i] * unitR;
      c.fillStyle = FAINT;
      c.fillRect(bx, Math.min(resCy, resCy - v0), bw, Math.abs(v0));
      var dv = alp[i] * F[i] * unitR;
      if (Math.abs(dv) > 0.4) {
        c.fillStyle = BLUE;
        c.fillRect(bx, Math.min(resCy - v0, resCy - v0 - dv), bw, Math.abs(dv));
      }
    }

    // gate arrows between rows
    for (i = 0; i < N; i++) {
      var cx = m + i * pitch + pitch / 2;
      var wA = 0.7 + 2.0 * alp[i] / 1.2;
      c.globalAlpha = gaA * (0.3 + 0.7 * Math.min(1, alp[i] * 1.5));
      c.strokeStyle = WARM;
      c.fillStyle = WARM;
      c.lineWidth = wA;
      line(cx, Y(141), cx, Y(128));
      c.lineWidth = 1;
      head(cx, Y(141), cx, Y(127), 4);
    }
    c.globalAlpha = 1;

    // feature row
    txt(fa > 0.5 ? 'F(h)   block output' : 'h   layer features (16 channels)', m, Y(154), 12, BLUE, 'left', W - 2 * m);
    c.strokeStyle = FAINT;
    line(m, featCy, W - m, featCy);
    if (nrm < 0.98) {
      c.setLineDash([3, 3]);
      c.globalAlpha = 1 - nrm;
      line(m, featCy - mu * (1 - nrm) * unitF, W - m, featCy - mu * (1 - nrm) * unitF);
      c.setLineDash([]);
      c.globalAlpha = 1;
    }
    for (i = 0; i < N; i++) {
      var fx = m + i * pitch + (pitch - bw) / 2;
      if (mod > 0.02 && fa < 0.9) {
        var gv = base[i] * unitF;
        c.globalAlpha = mod * (1 - fa) * 0.9;
        c.strokeStyle = FAINT;
        c.strokeRect(fx + 0.5, Math.min(featCy, featCy - gv), bw - 1, Math.abs(gv));
        c.globalAlpha = 1;
      }
      var hv = disp[i] * unitF;
      c.fillStyle = BLUE;
      c.globalAlpha = 0.9;
      c.fillRect(fx, Math.min(featCy, featCy - hv), bw, Math.abs(hv));
      c.globalAlpha = 1;
    }

    // detail text
    var l1, l2;
    if (phase === 0) { l1 = "h' = (h − mean) / std"; l2 = 'zero mean, unit spread in every layer'; }
    else if (phase === 1) {
      l1 = "h'' = (1 + γ)·h' + β";
      l2 = s < 0.3 ? 'low σ: this γ, β from MLP(σ)' : (s > 0.7 ? 'high σ: a different γ, β' : 'σ turning: γ, β follow');
    } else if (p < 0.12) { l1 = 'adaLN-Zero: the block starts as the identity,'; l2 = 'nothing changes (α = 0)'; }
    else { l1 = "x' = x + α·F(h)"; l2 = 'training grows α: mean α = ' + (p * meanAmp).toFixed(2); }
    c.globalAlpha = fadeIn;
    txt(l1, W / 2, Y(273), 12, INK, 'center', W - 2 * m - 4);
    txt(l2, W / 2, Y(289), 12, SEC, 'center', W - 2 * m - 4);
    c.globalAlpha = 1;

    // conditioning strip: dial
    var dR = clamp(W * 0.07, 20, 28), dCx = 14 + dR, dCy = Y(346);
    c.strokeStyle = FAINT;
    c.lineWidth = 3;
    c.beginPath(); c.arc(dCx, dCy, dR, -1.25 * Math.PI, 0.25 * Math.PI); c.stroke();
    var ang = -0.75 * Math.PI + s * 1.5 * Math.PI;
    c.strokeStyle = WARM;
    c.beginPath(); c.arc(dCx, dCy, dR, -1.25 * Math.PI, -Math.PI / 2 + ang); c.stroke();
    c.lineWidth = 2;
    line(dCx, dCy, dCx + Math.sin(ang) * dR * 0.8, dCy - Math.cos(ang) * dR * 0.8);
    c.lineWidth = 1;
    c.fillStyle = WARM;
    c.beginPath(); c.arc(dCx, dCy, 3, 0, 6.2832); c.fill();
    var sig = Math.exp(Math.log(0.02) + s * (Math.log(80) - Math.log(0.02)));
    txt('σ = ' + (sig < 1 ? sig.toFixed(2) : (sig < 10 ? sig.toFixed(1) : sig.toFixed(0))), dCx, dCy + dR + Y(15), 12, WARM, 'center');

    // MLP box
    var bxL = dCx + dR + 22, bxW = clamp(W * 0.17, 60, 130), bxH = Y(54);
    c.strokeStyle = WARM; c.fillStyle = WARM;
    arrow(dCx + dR + 4, dCy, bxL - 2, dCy);
    dot(dCx + dR + 4, dCy, bxL - 2, dCy, time, 0);
    c.lineWidth = 1.5;
    c.strokeRect(bxL, dCy - bxH / 2, bxW, bxH);
    c.lineWidth = 1;
    txt('MLP(σ)', bxL + bxW / 2, dCy + 4, 13, WARM, 'center', bxW - 6, true);

    // three vectors
    var labX = bxL + bxW + 22, vecX = labX + 50;
    var cw = Math.min(18, (W - vecX - m * 0.9 - 8) / N);
    var vecEnd = vecX + N * cw + 4;
    var rowsY = [Y(318), Y(346), Y(374)];
    var names = ['γ  scale', 'β  shift', 'α  gate'];
    var vals = [gam, bet, alp];
    var scl = [Y(13), Y(10), Y(9)];
    var aGB = 0.4 + 0.6 * (ease(t, 3.5, 4.2) - ease(t, 8.5, 9.0)) * f;
    var aA = 0.4 + 0.6 * ease(t, 8.6, 9.4) * f;
    var acts = [aGB, aGB, aA];
    for (var r = 0; r < 3; r++) {
      var ry = rowsY[r];
      c.globalAlpha = acts[r];
      c.strokeStyle = WARM; c.fillStyle = WARM;
      arrow(bxL + bxW, dCy, labX - 4, ry);
      dot(bxL + bxW, dCy, labX - 4, ry, time, r * 0.3);
      txt(names[r], labX, ry + 4, 12, WARM, 'left');
      c.strokeStyle = FAINT;
      line(vecX, ry, vecX + N * cw, ry);
      c.fillStyle = WARM;
      for (i = 0; i < N; i++) {
        var vh = vals[r][i] * scl[r];
        c.fillRect(vecX + i * cw + cw * 0.17, Math.min(ry, ry - vh), cw * 0.66, Math.max(Math.abs(vh), 1));
      }
      c.globalAlpha = 1;
    }

    // conditioning paths into the layer
    var x1 = W - m * 0.6, x2 = W - m * 0.25;
    c.strokeStyle = WARM; c.fillStyle = WARM;
    c.globalAlpha = aGB;
    line(vecEnd, rowsY[0], x1, rowsY[0]);
    line(vecEnd, rowsY[1], x1, rowsY[1]);
    line(x1, rowsY[0], x1, featCy);
    arrow(x1, featCy, W - m + 3, featCy);
    c.globalAlpha = aA;
    line(vecEnd, rowsY[2], x2, rowsY[2]);
    line(x2, rowsY[2], x2, Y(134));
    arrow(x2, Y(134), W - m + 3, Y(134));
    c.globalAlpha = 1;
  }
};
